-- CARINE TURISMO — estrutura final do painel
-- Pode executar este arquivo inteiro no SQL Editor do Supabase.

create table if not exists public.catalogo (
  id bigint generated by default as identity primary key,
  tipo text not null check (tipo in ('passeio','ingresso','hotel','evento')),
  dados jsonb not null default '{}'::jsonb,
  ordem integer not null default 999,
  created_at timestamptz not null default now()
);
alter table public.catalogo enable row level security;

create table if not exists public.categorias (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  nome text not null,
  tipo text not null default 'passeio' check (tipo in ('passeio','ingresso','hotel','evento')),
  imagem text not null default '',
  resumo text not null default '',
  ordem integer not null default 999,
  home boolean not null default false,
  ativo boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.categorias enable row level security;

create table if not exists public.banners (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  imagem text not null,
  destaque text not null default '',
  titulo text not null,
  texto text not null default '',
  botao_texto text not null default '',
  botao_link text not null default '',
  ordem integer not null default 999,
  ativo boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.banners enable row level security;

insert into public.categorias (slug,nome,tipo,imagem,resumo,ordem,home,ativo) values
('foz-do-iguacu','Foz do Iguaçu','passeio','https://imgcdn.bokun.tools/360afe49-e312-4e1c-b095-ab0873b2661d.jpeg','Cataratas, Itaipu, Parque das Aves, AquaFoz e muito mais.',10,true,true),
('paraguai','Paraguai','passeio','assets/images/paraguai-home.png','Compras em Ciudad del Este com ida e retorno combinados.',20,true,true),
('argentina','Argentina','passeio','assets/images/argentina-home.png','Feirinha, Cataratas Argentinas e experiências em Puerto Iguazú.',30,true,true),
('foz-ingressos','Foz do Iguaçu','ingresso','', 'Ingressos e experiências em Foz do Iguaçu.',10,false,true),
('eventos','Eventos','evento','', 'Eventos e experiências por temporada.',10,false,true),
('centro','Centro','hotel','', 'Hotéis na região central de Foz.',10,false,true),
('rodovia-cataratas','Rodovia das Cataratas','hotel','', 'Hotéis e resorts na região da Rodovia das Cataratas.',20,false,true)
on conflict (slug) do update set nome=excluded.nome,tipo=excluded.tipo,imagem=excluded.imagem,resumo=excluded.resumo,ordem=excluded.ordem,home=excluded.home,ativo=excluded.ativo;

insert into public.banners (slug,imagem,destaque,titulo,texto,botao_texto,botao_link,ordem,ativo) values
