('itaipu','https://www.adibra.com.br/Content/upload/photos/2723/turistas-2.jpg','ITAIPU BINACIONAL','Conheça os ícones de Foz com conforto.','Você escolhe o roteiro e a Carine cuida do deslocamento até o atrativo e da busca combinada.','Ver detalhes','detalhes.html?tipo=passeio&id=itaipu',20,true),
('macuco-safari','https://media.tacdn.com/media/attractions-splice-spp-210x118/07/90/b5/22.jpg','MACUCO SAFARI','Aventura também entra no roteiro.','Transporte até o Parque Nacional do Iguaçu para quem quer viver o Macuco Safari.','Conhecer opção','detalhes.html?tipo=passeio&id=macuco-safari',30,true),
('parque-das-aves','https://www.tangol.com/Blog/Fotos/parque-das-aves-birds-park-at-exuberant-iguazu-forest_0_201805231437130-resized.webp','PARQUE DAS AVES','Natureza, praticidade e um roteiro leve.','Combine Parque das Aves, Cataratas e outros pontos próximos no seu dia.','Ver detalhes','detalhes.html?tipo=passeio&id=parque-das-aves',40,true)
on conflict (slug) do update set imagem=excluded.imagem,destaque=excluded.destaque,titulo=excluded.titulo,texto=excluded.texto,botao_texto=excluded.botao_texto,botao_link=excluded.botao_link,ordem=excluded.ordem,ativo=excluded.ativo;

